gaAs(){return"\u064a\u0639\u0645\u0644 \u0627\u0644\u0646\u0638\u0627\u0645 \u0628\u0646\u0638\u0627\u0645 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643. \u0639\u0646\u062f \u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u0642\u062f \u064a\u062a\u0645 \u062a\u0642\u064a\u064a\u062f \u0627\u0644\u0648\u0635\u0648\u0644 \u0623\u0648 \u0625\u064a\u0642\u0627\u0641\u0647 \u0648\u0642\u062f \u064a\u062a\u0645 \u062a\u0648\u0641\u064a\u0631 \u0648\u0635\u0648\u0644 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u0642\u0637 \u0644\u0641\u062a\u0631\u0629 \u0633\u0645\u0627\u062d \u0645\u062d\u062f\u0648\u062f\u0629."},
gaAv(){return"\u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u062e\u062f\u0645\u0629"},
gaAu(){return"\u064a\u062d\u0642 \u0644\u0640 ProKliniK \u0625\u064a\u0642\u0627\u0641 \u0623\u0648 \u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u062e\u0627\u0644\u0641 \u0647\u0630\u0647 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0623\u0648 \u062a\u0634\u0643\u0644 \u062e\u0637\u0631\u0627\u064b \u0642\u0627\u0646\u0648\u0646\u064a\u0627\u064b \u0623\u0648 \u0623\u0645\u0646\u064a\u0627\u064b."},
gaAk(){return"\u0625\u062e\u0644\u0627\u0621 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0627\u0644\u0637\u0628\u064a\u0629"},
gaAj(){return"ProKliniK \u0647\u0648 \u0646\u0638\u0627\u0645 \u0625\u062f\u0627\u0631\u064a \u0641\u0642\u0637 \u0648\u0644\u0627 \u064a\u0642\u062f\u0645 \u0627\u0633\u062a\u0634\u0627\u0631\u0627\u062a \u0623\u0648 \u062a\u0634\u062e\u064a\u0635\u0627\u064b \u0623\u0648 \u0639\u0644\u0627\u062c\u0627\u064b \u0637\u0628\u064a\u0627\u064b. \u062a\u0642\u0639 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0627\u0644\u0637\u0628\u064a\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0639\u0644\u0649 \u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u0623\u0648 \u0627\u0644\u062c\u0647\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0629 \u0627\u0644\u0645\u0631\u062e\u0635\u0629."},
gayr(){return"\u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629"},
gayq(){return"\u062a\u0639\u062f \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0647\u064a \u0627\u0644\u0645\u062a\u062d\u0643\u0645 \u0641\u064a \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0628\u064a\u0646\u0645\u0627 \u064a\u0639\u0645\u0644 ProKliniK \u0643\u0645\u0639\u0627\u0644\u062c \u0644\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u064a\u062a\u0645 \u0630\u0644\u0643 \u0648\u0641\u0642 \u062a\u0639\u0644\u064a\u0645\u0627\u062a \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0648\u0627\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u0645\u0639\u0645\u0648\u0644 \u0628\u0647\u0627."},
gayi(){return"\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062a\u0645 \u062c\u0645\u0639\u0647\u0627"},
